We have
\begin{enumerate} 
\item[(1).] $\delta_2X =
(\frac{\delta_2 X_1}{X_1})\,X - B_0\,\delta_2$; 
\item[(2).] $X(y_j) =
\delta_2(X(y_{j-1})) - (\frac{\delta_2 X_1}{X_1})\,X(y_{j-1}) +
B_0\,y_j$.
\end{enumerate}

We have
\begin{equation}  X(y_j) \sim
\sum_{i = 0}^{j-1}a_{j,i}\,B_i\,y_{j-i}
\end{equation}
 where $a_{j,i}$ are
constants, with $a_{j,0} = j$.

Let $A\in \Lambda$ with the lowest rank and $r =
\mathrm{ord}(\Lambda) > 1$. Let $\mathbf{n}\in \mathcal{I}_A$ with the
highest degree and $A_\mathbf{n} = 1$, then for any $\mathbf{m} <
\mathbf{n}$,
\begin{equation}
 X(A_\mathbf{m}) = (C({\mathbf{n}}) -
C({\mathbf{m}}))\,B_0\,A_{\mathbf{m}}
-\sum_{i=1}^{r-1}\sum_{j=i+1}^{r}(m_j+1)\,a_{j,i}\,B_i\,A_{{b_i^j}(\mathbf{m})}
\end{equation}
where $A_{\mathbf{m}} = 0$ if $\mathbf{m}\not\in \mathcal{I}_A$.

If $u\not=0$ satisfies
\begin{equation}
 X\,u = B_0\,u
\end{equation}
then there exists a first integral $\omega$ of $X$ such that
$$\delta_2\omega = u.$$
